variable {V : Type u} {n : ℕ}

-- Define the adjacency relation as a function from V x V to Prop
def adj : V → V → Prop := λ x y, RelMap adj [x, y]

-- Define irreflexivity
def irreflexive : (V → V → Prop) → Prop := λ R, ∀ x, ¬ R x x

-- Define symmetry
def symmetric : (V → V → Prop) → Prop := λ R, ∀ x y, R x y → R y x

-- Define the theory of simple graphs
def Theory : Structure := {
  axioms := {
    irreflexivity : irreflexive adj,
    symmetry : symmetric adj
  }
}

-- Define the satisfaction of a theory
def satisfiesTheory : Structure → (V → Prop) → Prop := λ S, ∀ p, S.axioms p

-- Theorem: V models Theory.simpleGraph if and only if the adjacency relation is irreflexive and symmetric
theorem modelsSimpleGraph_iff_adj_relation : 
  V → satisfiesTheory Theory adj ↔ irreflexive adj ∧ symmetric adj :=
begin
  split,
  {
    -- Assume V satisfies Theory.simpleGraph
    assume h : satisfiesTheory Theory adj,
    -- Show irreflexivity
    have irreflexivity_adj : irreflexive adj,
    {
      intros x,
      have h_irreflexivity : ¬ adj x x,
      {
        apply h,
        exact (Theory.axioms.irreflexivity x),
      },
      exact h_irreflexivity,
    },
    -- Show symmetry
    have symmetry_adj : symmetric adj,
    {
      intros x y h_adj,
      have h_symmetry : adj y x,
      {
        apply h,
        exact (Theory.axioms.symmetry x y h_adj),
      },
      exact h_symmetry,
    },
    -- Combine irreflexivity and symmetry
    exact and.intro irreflexivity_adj symmetry_adj,
