      -- Combine the two inclusions
      exact h1.trans h2,
    },

    -- Show that the intersection of all maximal ideals containing {0} is the same as the intersection of all maximal ideals of R
    have h3 : maximal_ideals = Ring.jacobson R,
    {
      -- Show that maximal_ideals is a subset of Ring.jacobson R
      have h4 : ∀ (m : Ideal R), m ∈ maximal_ideals → m ∈ Ring.jacobson R,
      {
        intros m h2,
        -- Since R ⊆ m, we have {0 : R} ⊆ m
